import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine } from '../src/invoices.js';

test('createInvoice: creates invoice with valid input', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.issueDate, '2025-10-07');
  assert.equal(result.value.status, 'draft');
  assert.equal(result.value.lines.length, 1);

  const line = result.value.lines[0];
  assert.equal(line.sku, 'DEV-HOUR');
  assert.equal(line.name, 'Development (hour)');
  assert.equal(line.qty, 5);
  assert.equal(line.unitPrice, 9500);
  assert.equal(line.vatRate, 21);
});

test('createInvoice: creates invoice with multiple lines', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-09-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'LOGO-PACK', qty: 1 },
      { sku: 'STICKER', qty: 100 },
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 3);
  assert.equal(result.value.lines[0].name, 'Development (hour)');
  assert.equal(result.value.lines[1].name, 'Logo package');
  assert.equal(result.value.lines[2].name, 'Sticker sheet');
});

test('createInvoice: returns CUSTOMER_NOT_FOUND for unknown customer', () => {
  const result = createInvoice({
    customerId: 'UNKNOWN',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'CUSTOMER_NOT_FOUND');
});

test('createInvoice: returns DATE_INVALID for wrong format', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '07-10-2025',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'DATE_INVALID');
});

test('createInvoice: returns DATE_INVALID for invalid date values', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-30',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'DATE_INVALID');
});

test('createInvoice: returns DATE_INVALID for missing date', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'DATE_INVALID');
});

test('createInvoice: returns NO_LINES for empty lines array', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'NO_LINES');
});

test('createInvoice: returns NO_LINES for missing lines', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: null,
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'NO_LINES');
});

test('createInvoice: returns QTY_INVALID for non-integer quantity', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1.5 }],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'QTY_INVALID');
});

test('createInvoice: returns QTY_INVALID for zero quantity', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 0 }],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'QTY_INVALID');
});

test('createInvoice: returns QTY_INVALID for negative quantity', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: -5 }],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'QTY_INVALID');
});

test('createInvoice: returns UNKNOWN_SKU for missing SKU', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'UNKNOWN-SKU', qty: 1 }],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'UNKNOWN_SKU');
});

test('createInvoice: does not mutate input', () => {
  const input = {
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  };
  const inputCopy = JSON.parse(JSON.stringify(input));

  createInvoice(input);

  assert.deepEqual(input, inputCopy);
});

test('createInvoice: accepts valid dates', () => {
  const validDates = [
    '2025-01-31',
    '2025-02-28',
    '2024-02-29',
    '2000-12-31',
    '1999-01-01',
  ];

  for (const date of validDates) {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: date,
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    });
    assert.equal(result.ok, true, `Should accept date ${date}`);
  }
});

test('createInvoice: rejects leap year dates incorrectly', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-29',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'DATE_INVALID');
});

test('lineTotal: calculates qty times unitPrice', () => {
  const line = { qty: 5, unitPrice: 9500 };
  assert.equal(lineTotal(line), 47500);
});

test('lineTotal: handles qty of 1', () => {
  const line = { qty: 1, unitPrice: 120000 };
  assert.equal(lineTotal(line), 120000);
});

test('lineTotal: handles large quantities', () => {
  const line = { qty: 1000, unitPrice: 1000 };
  assert.equal(lineTotal(line), 1000000);
});

test('lineTotal: does not mutate input', () => {
  const line = { qty: 5, unitPrice: 9500 };
  const lineCopy = { ...line };
  lineTotal(line);
  assert.deepEqual(line, lineCopy);
});

test('invoiceTotals: sums single line', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 9500 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 47500);
  assert.equal(totals.total, 47500);
});

test('invoiceTotals: sums multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 9500 },
      { qty: 1, unitPrice: 120000 },
      { qty: 100, unitPrice: 50 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 95000 + 120000 + 5000);
  assert.equal(totals.total, 220000);
});

test('invoiceTotals: returns zero for empty invoice', () => {
  const invoice = { lines: [] };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 0);
  assert.equal(totals.total, 0);
});

test('invoiceTotals: total equals subtotal', () => {
  const invoice = {
    lines: [
      { qty: 3, unitPrice: 1000 },
      { qty: 2, unitPrice: 2000 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, totals.total);
});

test('invoiceTotals: does not mutate input', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 9500 }],
  };
  const invoiceCopy = JSON.parse(JSON.stringify(invoice));
  invoiceTotals(invoice);
  assert.deepEqual(invoice, invoiceCopy);
});

test('invoiceTotals: works with real invoice from createInvoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });

  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  const expectedSubtotal = 10 * 9500 + 1 * 120000;
  assert.equal(totals.subtotal, expectedSubtotal);
  assert.equal(totals.total, expectedSubtotal);
});

test('addLine: adds a new line to invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  const updated = addLine(result.value, { sku: 'LOGO-PACK', qty: 1 });

  assert.equal(updated.ok, true);
  assert.equal(updated.value.lines.length, 2);
  assert.equal(updated.value.lines[1].sku, 'LOGO-PACK');
  assert.equal(updated.value.lines[1].name, 'Logo package');
  assert.equal(updated.value.lines[1].qty, 1);
  assert.equal(updated.value.lines[1].unitPrice, 120000);
});

test('addLine: increases qty if SKU already exists', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  const updated = addLine(result.value, { sku: 'DEV-HOUR', qty: 3 });

  assert.equal(updated.ok, true);
  assert.equal(updated.value.lines.length, 1);
  assert.equal(updated.value.lines[0].qty, 8);
});

test('addLine: returns QTY_INVALID for non-integer qty', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  const updated = addLine(result.value, { sku: 'LOGO-PACK', qty: 1.5 });

  assert.equal(updated.ok, false);
  assert.equal(updated.error, 'QTY_INVALID');
});

test('addLine: returns QTY_INVALID for zero qty', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  const updated = addLine(result.value, { sku: 'LOGO-PACK', qty: 0 });

  assert.equal(updated.ok, false);
  assert.equal(updated.error, 'QTY_INVALID');
});

test('addLine: returns UNKNOWN_SKU for invalid SKU', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  const updated = addLine(result.value, { sku: 'INVALID-SKU', qty: 1 });

  assert.equal(updated.ok, false);
  assert.equal(updated.error, 'UNKNOWN_SKU');
});

test('addLine: returns NOT_DRAFT if invoice is not draft', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-10-07',
    status: 'sent',
    lines: [{ sku: 'DEV-HOUR', qty: 5, name: 'Development (hour)', unitPrice: 9500, vatRate: 21 }],
  };

  const updated = addLine(invoice, { sku: 'LOGO-PACK', qty: 1 });

  assert.equal(updated.ok, false);
  assert.equal(updated.error, 'NOT_DRAFT');
});

test('addLine: does not mutate original invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  const invoiceCopy = JSON.parse(JSON.stringify(result.value));

  addLine(result.value, { sku: 'LOGO-PACK', qty: 1 });

  assert.deepEqual(result.value, invoiceCopy);
});

test('removeLine: removes a line from invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });

  assert.equal(result.ok, true);
  const updated = removeLine(result.value, 'DEV-HOUR');

  assert.equal(updated.ok, true);
  assert.equal(updated.value.lines.length, 1);
  assert.equal(updated.value.lines[0].sku, 'LOGO-PACK');
});

test('removeLine: returns LINE_NOT_FOUND if SKU not on invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  const updated = removeLine(result.value, 'LOGO-PACK');

  assert.equal(updated.ok, false);
  assert.equal(updated.error, 'LINE_NOT_FOUND');
});

test('removeLine: returns NO_LINES if removing last line', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  const updated = removeLine(result.value, 'DEV-HOUR');

  assert.equal(updated.ok, false);
  assert.equal(updated.error, 'NO_LINES');
});

test('removeLine: returns NOT_DRAFT if invoice is not draft', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-10-07',
    status: 'paid',
    lines: [
      { sku: 'DEV-HOUR', qty: 5, name: 'Development (hour)', unitPrice: 9500, vatRate: 21 },
      { sku: 'LOGO-PACK', qty: 1, name: 'Logo package', unitPrice: 120000, vatRate: 21 },
    ],
  };

  const updated = removeLine(invoice, 'LOGO-PACK');

  assert.equal(updated.ok, false);
  assert.equal(updated.error, 'NOT_DRAFT');
});

test('removeLine: does not mutate original invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });

  assert.equal(result.ok, true);
  const invoiceCopy = JSON.parse(JSON.stringify(result.value));

  removeLine(result.value, 'LOGO-PACK');

  assert.deepEqual(result.value, invoiceCopy);
});

test('addLine and removeLine: can add and remove multiple times', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);

  let invoice = result.value;
  let updated = addLine(invoice, { sku: 'LOGO-PACK', qty: 1 });
  assert.equal(updated.ok, true);
  invoice = updated.value;

  updated = addLine(invoice, { sku: 'STICKER', qty: 10 });
  assert.equal(updated.ok, true);
  invoice = updated.value;

  assert.equal(invoice.lines.length, 3);

  updated = removeLine(invoice, 'LOGO-PACK');
  assert.equal(updated.ok, true);
  invoice = updated.value;

  assert.equal(invoice.lines.length, 2);
  assert.equal(invoice.lines[0].sku, 'DEV-HOUR');
  assert.equal(invoice.lines[1].sku, 'STICKER');
});

